\right.
\end{align}
where $Z_r$ denotes $(1-q)^2\frac{(X_rX_{r+2}-X_{r+1}^2)(X_r X_{r+1}-qX_{r+1}X_{r+2})}{(X_r-X_{r+1})^2(X_{r+1}-X_{r+2})^2}.$

The degenerate affine Yokonuma-Hecke algebra, denoted by $\widehat{Y}_{r,n}(1)$, is an $\mathcal{R}$-associative algebra generated by the elements $t_{1},\ldots,t_{n},f_{1},\ldots,f_{n-1},y_1,\ldots, y_{n}$ in which the generators $t_{1},\ldots,t_{n},g_{1},$ $\ldots,g_{n-1}$ satisfy the following relations:
\begin{align}
f_if_j&=f_jf_i \qquad \qquad\qquad\quad\hspace{0.3cm}\mbox{for all $i,j=1,\ldots,n-1$ such that $\vert i-j\vert \geq 2$;}\label{drel-def-Y1}\\[0.1em]
f_if_{i+1}f_i&=f_{i+1}f_if_{i+1} \qquad \quad\qquad\hspace{0.05cm}\mbox{for all $i=1,\ldots,n-2$;}\label{drel-def-Y2}\\[0.1em]
t_it_j&=t_jt_i \qquad\qquad\qquad\qquad  \mbox{for all $i,j=1,\ldots,n$;}\label{drel-def-Y3}\\[0.1em]
f_it_j&=t_{s_i(j)}f_i \quad \quad\qquad\qquad\hspace{0.25cm}\mbox{for all $i=1,\ldots,n-1$ and $j=1,\ldots,n$;}\label{drel-def-Y4}\\[0.1em]
t_i^r&=1 \quad \qquad\qquad\qquad\qquad\mbox{for all $i=1,\ldots,n$;}\label{drel-def-Y5}\\[0.2em]
f_{i}^{2}&=1 \qquad \hspace{2.71cm}\mbox{for all $i=1,\ldots,n-1$;}\label{drel-def-Y6}
\end{align}
together with the following relations concerning the generators $y_1,\ldots, y_{n}$:
\begin{align}
y_{i}y_{j}&=y_{j}y_{i};\label{drel-def-Y7}\\[0.1em]
f_{i}y_{i+1}&=y_{i}f_{i}+e_{i};\label{drel-def-Y8}\\[0.1em]
f_{i}y_{j}&=y_{j}f_{i} \qquad \qquad \quad\mbox{for all $j\neq i, i+1$;}\label{drel-def-Y9}\\[0.1em]
t_{j}y_{i}&=y_{i}t_{j} \hspace{0.07cm}\qquad \qquad\quad\mbox{for all $i, j=1,\ldots,n$;}\label{drel-def-Y10}
\end{align}
where for each $1\leq i\leq n-1$,
$$e_{i} :=\frac{1}{r}\sum\limits_{s=0}^{r-1}t_{i}^{s}t_{i+1}^{-s}.$$

