g_{i}X_{i}^{-1}&=X_{i+1}^{-1}g_{i}+(q-1)e_{i}X_{i}^{-1}, \label{gxxg2}\\
X_{i}^{-1}g_{i}&=g_{i}X_{i+1}^{-1}+(q-1)e_{i}X_{i}^{-1}.\label{gxxg3}
\end{align}

Let $\widehat{Y}_{r,n}^{k}=k\otimes_{\mathcal{R}}\widehat{Y}_{r,n}(q)$ and let $M$ be a $\widehat{Y}_{r,n}^{k}$-module. Given $\alpha=(\nu, j)\in K^{n},$ we denote by $M_{\alpha}$ the subspace of $M$ on which $X_{a}-\nu_{a}$ acts locally nilpotently for $1\leq a\leq n,$ and simultaneously, $t_{a}-\zeta^{j_{a}}$ acts as zero for $1\leq a\leq n.$ Let $\mathcal{C}_{K}$ be the category of finitely generated $\widehat{Y}_{r,n}^{k}$-modules $M$ such that $M=\bigoplus_{\alpha\in K^{n}}M_{\alpha}.$

Given an object $M\in \mathcal{C}_{K}$, we can write $M$ as the direct sum of its weight spaces (simultaneous generalized eigenspaces):
\begin{equation}
M(\nu, j)=\{v\in M\:|\:(X_{a}-\nu_{a})^{N}v=(t_{a}-\zeta^{j_{a}})v=0\text{ for all }1\leq a\leq n\text{ and }N\gg 0\}.\label{M-J}
\end{equation}
Considering the weight space decomposition of the regular module, we deduce that there is a family $\{e(\nu,j)\}_{(\nu,j)\in K^{n}}$ of mutually orthogonal idempotents in $\widehat{Y}_{r,n}^{k}$ such that $e(\nu,j)M=M(\nu, j)$ for each $M\in \mathcal{C}_{K}$. In fact, each $e(\nu, j)$ lies in the commutative subalgebra generated by $X_{1}^{\pm1},\ldots, X_{n}^{\pm1}, t_{1},\ldots,t_{n}$, all but finitely many of the $e(\nu, j)$'s are zero, and their sum is the identity element in $\widehat{Y}_{r,n}^{k}.$


By definition, we easily get the following equalities: for $1\leq i\leq n-1$ and $(\nu, j)\in K^{n}$,
\begin{equation}
e_{i}e(\nu, j)=0 \text{ if } j_{i}\neq j_{i+1} ~~~~\text{ and }~~~~e_{i}e(\nu, j)=e(\nu, j) \text{ if }j_{i}=j_{i+1}.\label{eee}
\end{equation}

From \eqref{gxxg}, \eqref{gxxg1} and \eqref{eee}, we immediately get the following lemma.

\begin{lemma}
For $1\leq i\leq n-1$ and $(\nu, j)\in K^{n}$ with $j_{i}\neq j_{i+1},$ we have
\begin{equation}
g_{i}X_{i+1}e(\nu, j)=X_{i}g_{i}e(\nu, j) ~~~~\text{ and }~~~~X_{i+1}g_{i}e(\nu, j)=g_{i}X_{i}e(\nu, j).\label{gxe-xge}
\end{equation}
\end{lemma}

We also have the following lemma.
\begin{lemma}
If $1\leq i\leq n-1$ and $(\nu, j)\in K^{n}$ with $j_{i}\neq j_{i+1},$ then we have
\begin{equation}
g_{i}e(\nu, j)=e(s_{i}\cdot(\nu, j))g_{i}.\label{ge-eg}
\end{equation}
\end{lemma}

\begin{proof}
From \eqref{rel-def-Y4} and \eqref{gxe-xge}, we see that $g_{i}e(\nu, j)$ maps $M(\nu, j)$ to $M(s_{i}\cdot(\nu, j))$ for any $M\in \mathcal{C}_{K}.$
Thus, both $g_{i}e(\nu, j)$ and $e(s_{i}\cdot(\nu, j))g_{i}$ map $M(\nu', j')$ to zero unless $(\nu', j')=(\nu, j)$, and they map each $m\in M(\nu, j)$ to $g_{i}m.$ We get \eqref{ge-eg}.
\end{proof}


