\subsection{An equivalence of categories}
Recall that $\mathcal{C}_{K}$ is the category of finitely generated $\widehat{Y}_{r,n}^{k}$-modules $M$ such that $M=\bigoplus_{\alpha\in K^{n}}M_{\alpha}.$ We denote by $\mathcal{C}_{\Gamma}^{0}$ the category of finitely generated $H_{n}(\Gamma)$-modules $M$ such that for every $\alpha\in K^{n},$ $x_{a}1_{\alpha}$ acts locally nilpotently on $1_{\alpha}M$ for $1\leq a\leq n.$

Now we can state the main theorem of this paper.
\begin{theorem}\label{Morita-equi}
There is an equivalence of categories $\Phi: \mathcal{C}_{\Gamma}^{0}\rightarrow \mathcal{C}_{K}$ given by $M\mapsto M,$ and where for each $\alpha=(\nu, j)\in K^{n},$ $t_{a}$ acts on $1_{\alpha}M$ by $\zeta^{j_{a}},$ $X_{a}$ acts on $1_{\alpha}M$ by $\nu_{a}(x_{a}+1)$ for $1\leq a\leq n,$ and $g_{i}$ acts on $1_{\alpha}M$ by $\tau_{i}Q_{i}(\nu, j)-P_{i}(\nu, j)$ for $1\leq i\leq n-1.$

The inverse functor $\Psi: \mathcal{C}_{K}\rightarrow \mathcal{C}_{\Gamma}^{0}$ is given by $N\mapsto N,$ where for each $\alpha=(\nu, j)\in K^{n},$ $1_{\alpha}$ acts on $N$ by $e(\nu, j),$ $x_{a}$ acts on $N_{\alpha}$ by $\nu_{a}^{-1}X_{a}-1$ for $1\leq a\leq n,$ and $\tau_{i}$ acts on $N_{\alpha}$ by $\Phi_{i}Q_{i}'(\nu, j)^{-1}=(g_{i}+P_{i}'(\nu, j))Q_{i}'(\nu, j)^{-1}$ for $1\leq i\leq n-1,$ where $P_{i}'(\nu, j)$ and $Q_{i}'(\nu, j)$ are defined by replacing $x_{i}$ with $\nu_{i}^{-1}X_{i}-1$ in the expressions of $P_{i}(\nu, j)$ and $Q_{i}(\nu, j).$
\end{theorem}



\section{Proof of the main theorem}

In this section we prove the main theorem \ref{Morita-equi}, which is motivated by the work of [BK1] and [Ro].\vspace{0.3cm}

{\it Proof of Theorem \ref{Morita-equi}} We first verify that the actions under $\Phi$ of the generators of $\widehat{Y}_{r,n}^{k}$ satisfy the relations \eqref{rel-def-Y1}-\eqref{rel-def-Y10}.

The relation \eqref{rel-def-Y1} easily follows from \eqref{rel-def-QHA3} and \eqref{rel-def-QHA4}.

The relations \eqref{rel-def-Y3} and \eqref{rel-def-Y5} easily follow from the definition.

The relation \eqref{rel-def-Y4} easily follows from the next fact:
\begin{equation*}
\zeta^{j_{b}}P_{a}(\nu, j)=\zeta^{j_{s_{a}(b)}}P_{a}(\nu, j)\quad\text{ for any }1\leq a\leq n-1, ~1\leq b\leq n\text{ and }(\nu, j)\in K^{n}.
\end{equation*}

Next we check the relation \eqref{rel-def-Y6}, that is, $g_{i}^{2}\diamond 1_{(\nu, j)}m=(q+(q-1)g_{i}e_{i})\diamond 1_{(\nu, j)}m$ for all $(\nu, j)\in K^{n}$ and $m\in M$ with an $M\in \mathcal{C}_{\Gamma}^{0}.$ To simplify notation for the remainder of the proof, we no longer write the elements ``$m$" on the right hand side of all expressions, but remember it is always there. By definition, we have
\begin{align*}
&g_{i}^{2}\diamond 1_{(\nu, j)}\\=&(\tau_{i}Q_{i}(s_{i}\cdot(\nu, j))\tau_{i}Q_{i}(\nu, j)-P_{i}(s_{i}\cdot(\nu, j))\tau_{i}Q_{i}(\nu, j)-\tau_{i}Q_{i}(\nu, j)P_{i}(\nu, j)+P_{i}(\nu, j)^{2})1_{(\nu, j)}.
\end{align*}

If $(\nu_{i}, j_{i})=(\nu_{i+1}, j_{i+1}),$ by $\tau_{i}^{2}1_{(\nu, j)}=0,$ $e_{i}\diamond 1_{(\nu, j)}=1$ and $\partial_{i}(qx_{i+1}+q-x_{i}-1)=q+1$ and \eqref{commu-relations}, we deduce that
\begin{align*}
g_{i}^{2}\diamond 1_{(\nu, j)}&=(\tau_{i}(qx_{i+1}+q-x_{i}-1)\tau_{i}Q_{i}(\nu, j)-2\tau_{i}Q_{i}(\nu, j)+1)1_{(\nu, j)}\\
&=((q+1)\tau_{i}Q_{i}(\nu, j)-2\tau_{i}Q_{i}(\nu, j)+1)1_{(\nu, j)}\\
&=(q+(q-1)g_{i}e_{i})\diamond 1_{(\nu, j)}.
\end{align*}

If $j_{i}=j_{i+1}$ and $\nu_{i}\neq \nu_{i+1},$ by $e_{i}\diamond 1_{(\nu, j)}=1$, \eqref{commu-relations}, \eqref{P-relations1} and \eqref{Q-P-relations}, we have
\begin{align*}
&g_{i}^{2}\diamond 1_{(\nu, j)}\\=&((\tau_{i}^{2}){}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))Q_{i}(\nu, j)-\tau_{i}(P_{i}(\nu, j)+{}^{s_{i}}P_{i}(s_{i}\cdot(\nu, j)))Q_{i}(\nu, j)+P_{i}(\nu, j)^{2})1_{(\nu, j)}\\
=&((1-P_{i}(\nu, j))(q+P_{i}(\nu, j))+(q-1)\tau_{i}Q_{i}(\nu, j)+P_{i}(\nu, j)^{2})1_{(\nu, j)}\\
=&(q+(q-1)g_{i}e_{i})\diamond 1_{(\nu, j)}.
\end{align*}

If $j_{i}\neq j_{i+1},$ by $e_{i}\diamond 1_{(\nu, j)}=0$, $P_{i}(\nu, j)=0$, \eqref{commu-relations} and \eqref{Q-P-relations}, we have
\begin{align*}
g_{i}^{2}\diamond 1_{(\nu, j)}&=(\tau_{i}^{2}){}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))Q_{i}(\nu, j)1_{(\nu, j)}\\
&=(1-P_{i}(\nu, j))(q+P_{i}(\nu, j))1_{(\nu, j)}\\
&=q1_{(\nu, j)}=(q+(q-1)g_{i}e_{i})\diamond 1_{(\nu, j)}.
\end{align*}

To prove \eqref{rel-def-Y8}, it suffices to show that \eqref{X2n} holds. Since we have proved \eqref{rel-def-Y6}, it suffices to show that \eqref{gxxg} holds.

If $(\nu_{i}, j_{i})=(\nu_{i+1}, j_{i+1}),$ by $e_{i}\diamond 1_{(\nu, j)}=1$ and \eqref{commu-relations}, we deduce that
\begin{align*}
X_{i}g_{i}\diamond 1_{(\nu, j)}&=X_{i}\diamond (\tau_{i}Q_{i}(\nu, j)-P_{i}(\nu, j))1_{(\nu, j)}\\
&=\nu_{i+1}(x_{i}+1)\tau_{i}Q_{i}(\nu, j)1_{(\nu, j)}-\nu_{i}(x_{i}+1)P_{i}(\nu, j)1_{(\nu, j)}\\
&=(\nu_{i}\tau_{i}(x_{i+1}+1)-\nu_{i})Q_{i}(\nu, j)1_{(\nu, j)}-\nu_{i}(x_{i}+1)P_{i}(\nu, j)1_{(\nu, j)}\\
&=\nu_{i}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)}-\nu_{i}(q(x_{i+1}+1)-(x_{i}+1)+(x_{i}+1))1_{(\nu, j)}\\
&=\nu_{i}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)}-q\nu_{i}(x_{i+1}+1)1_{(\nu, j)},
\end{align*}
and
\begin{align*}
\hspace{-0.6cm}(g_{i}+(1-q)e_{i})X_{i+1}\diamond 1_{(\nu, j)}&=(\tau_{i}Q_{i}(\nu, j)-P_{i}(\nu, j)+(1-q))\nu_{i+1}(x_{i+1}+1)1_{(\nu, j)}\\
&=\nu_{i}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)}-q\nu_{i}(x_{i+1}+1)1_{(\nu, j)}.
\end{align*}


If $j_{i}=j_{i+1}$ and $\nu_{i}\neq \nu_{i+1},$ by $e_{i}\diamond 1_{(\nu, j)}=1$ and \eqref{commu-relations}, we have
\begin{align*}
X_{i}g_{i}\diamond 1_{(\nu, j)}&=\nu_{i+1}(x_{i}+1)\tau_{i}Q_{i}(\nu, j)1_{(\nu, j)}-\nu_{i}(x_{i}+1)P_{i}(\nu, j)1_{(\nu, j)}\\
&=\nu_{i+1}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)}-\nu_{i}(x_{i}+1)P_{i}(\nu, j)1_{(\nu, j)},
\end{align*}
and
\begin{align*}
&(g_{i}+(1-q)e_{i})X_{i+1}\diamond 1_{(\nu, j)}\\=&(\tau_{i}Q_{i}(\nu, j)-P_{i}(\nu, j)+(1-q))\nu_{i+1}(x_{i+1}+1)1_{(\nu, j)}\\
=&\nu_{i+1}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)}+\nu_{i+1}(x_{i+1}+1)(1-q)\big(1+\frac{\nu_{i+1}(x_{i+1}+1)}{\nu_{i}(x_{i}+1)-\nu_{i+1}(x_{i+1}+1)}\big)\\
=&\nu_{i+1}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)}-\nu_{i}(x_{i}+1)P_{i}(\nu, j)1_{(\nu, j)}.
\end{align*}

If $j_{i}\neq j_{i+1},$ by $e_{i}\diamond 1_{(\nu, j)}=0$, $P_{i}(\nu, j)=0$ and \eqref{commu-relations}, we have
\begin{align*}
X_{i}g_{i}\diamond 1_{(\nu, j)}=\nu_{i+1}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)},
\end{align*}
and
\begin{align*}
(g_{i}+(1-q)e_{i})X_{i+1}\diamond 1_{(\nu, j)}=\nu_{i+1}\tau_{i}(x_{i+1}+1)Q_{i}(\nu, j)1_{(\nu, j)}.
\end{align*}

To prove \eqref{rel-def-Y9}, it suffices to prove \eqref{giXj}, which easily follows from \eqref{rel-def-QHA4}.

To prove \eqref{rel-def-Y10}, it suffices to prove \eqref{xyyx}, which immediately follows from the definition and \eqref{rel-def-QHA2}.

Finally we need to check the braid relations (2.2). Without loss of generality we assume that $i=1$ and $n=3,$ and we need to show that $g_{2}g_{1}g_{2}\diamond 1_{(\nu, j)}=g_{1}g_{2}g_{1}\diamond 1_{(\nu, j)},$ where $\nu=(\nu_1, \nu_2, \nu_3)$, $j=(j_1, j_2, j_3)$ and $(\nu, j)\in K^{3}.$

If $j_1=j_2=j_3$, we set $r:=\nu_1, s:=\nu_2, t:=\nu_3.$ We stop writing $\diamond 1_{(\nu, j)}$ on the right hand side of all expressions and stop writing $j=(j_1, j_2, j_3)$ in the expressions of $Q_{a}(\nu, j)$ and $P_{a}(\nu, j)$, that is, we write $Q_{a}(\nu)$ instead of $Q_{a}(\nu, j)$ and $P_{a}(\nu)$ instead of $P_{a}(\nu, j)$ for $a=1,2.$ By definition, $g_{2}g_{1}g_{2}$ and $g_{1}g_{2}g_{1}$ equal
\begin{equation}\label{ELPQ}
\begin{split}
&-P_2(rst)P_1(rst)P_2(rst)+ \tau_2Q_2(rst)P_1(rst)P_2(rst)
\\
&+ P_2(srt)\tau_1Q_1(rst)P_2(rst)
-\tau_2Q_2(srt)\tau_1Q_1(rst)P_2(rst)
\\
&+ P_2(rts)P_1(rts)\tau_2Q_2(rst)
- \tau_2Q_2(rts)P_1(rts)\tau_2Q_2(rst)
\\
&- P_2(trs)\tau_1Q_1(rts)\tau_2Q_2(rst)
+ \tau_2Q_2(trs)\tau_1Q_1(rts)\tau_2Q_2(rst),
\end{split}
\end{equation}
and
\begin{equation}\label{ERPQ}
\begin{split}
&-P_1(rst)P_2(rst)P_1(rst)+ \tau_1Q_1(rst)P_2(rst)P_1(rst)
\\&+ P_1(rts)\tau_2Q_2(rst)P_1(rst)
-\tau_1Q_1(rts)\tau_2Q_2(rst)P_1(rst)
\\&+ P_1(srt)P_2(srt)\tau_1Q_1(rst)
- \tau_1Q_1(srt)P_2(srt)\tau_1Q_1(rst)
\\& - P_1(str)\tau_2Q_2(srt)\tau_1Q_1(rst)
+ \tau_1Q_1(str)\tau_2Q_2(srt)\tau_1Q_1(rst),
\end{split}
\end{equation}
respectively. We have to show that \eqref{ELPQ} equals \eqref{ERPQ}. In order to show this, we compare various $\tau$-coefficients after commuting all $\tau$'s to the left using \eqref{commu-relations}. Then we need to consider five cases.

\subsubsection*{Case 1: $r, s, t$ are all different.}

\

\vspace{0.35cm}\noindent By \eqref{commu-relations}, \eqref{ELPQ} equals

\begin{equation*}
\begin{split}
&-P_2(rst)P_1(rst)P_2(rst)+ \tau_2Q_2(rst)P_1(rst)P_2(rst)
\\
&+ \tau_1{}^{s_{1}}P_2(srt)Q_1(rst)P_2(rst)
-\tau_2\tau_1{}^{s_{1}}Q_2(srt)Q_1(rst)P_2(rst)
\\
&+ \tau_2{}^{s_{2}}P_2(rts){}^{s_{2}}P_1(rts)Q_2(rst)
- (\tau_2^{2}){}^{s_{2}}Q_2(rts){}^{s_{2}}P_1(rts)Q_2(rst)
\\
&- \tau_1\tau_2{}^{s_{2}s_{1}}P_2(trs){}^{s_{2}}Q_1(rts)Q_2(rst)
+ \tau_2\tau_1\tau_2{}^{s_{2}s_{1}}Q_2(trs){}^{s_{2}}Q_1(rts)Q_2(rst),
\end{split}
\end{equation*}
and \eqref{ERPQ} equals
\begin{equation*}
\begin{split}
&-P_1(rst)P_2(rst)P_1(rst)+ \tau_1Q_1(rst)P_2(rst)P_1(rst)
\\&+ \tau_2{}^{s_{2}}P_1(rts)Q_2(rst)P_1(rst)
-\tau_1\tau_2{}^{s_{2}}Q_1(rts)Q_2(rst)P_1(rst)
\\&+ \tau_1{}^{s_{1}}P_1(srt){}^{s_{1}}P_2(srt)Q_1(rst)
- (\tau_1^{2}){}^{s_{1}}Q_1(srt){}^{s_{1}}P_2(srt)Q_1(rst)
\\& - \tau_2\tau_1{}^{s_{1}s_{2}}P_1(str){}^{s_{1}}Q_2(srt)Q_1(rst)
+ \tau_1\tau_2\tau_1{}^{s_{1}s_{2}}Q_1(str){}^{s_{1}}Q_2(srt)Q_1(rst).
\end{split}
\end{equation*}

Since $r,s, t$ are all different, we have $\tau_2\tau_1\tau_2=\tau_1\tau_2\tau_1,$ and their corresponding coefficients are equal to each other by \eqref{Q-relations1}. The corresponding $\tau_1\tau_2$-coefficients and $\tau_2\tau_1$-coefficients are equal to each other by \eqref{P-relations2}. For the $\tau_1$-coefficients, it suffices to prove that
\begin{equation*}
{}^{s_{1}}P_2(srt)P_2(rst)-P_2(rst)P_1(rst)={}^{s_{1}}P_1(srt){}^{s_{1}}P_2(srt).
\end{equation*}
We have
\begin{align*}
&{}^{s_{1}}P_2(srt)P_2(rst)-P_2(rst)P_1(rst)\\=&\big(\frac{t(x_{3}+1)}{r(x_{1}+1)-t(x_{3}+1)}-\frac{s(x_{2}+1)}{r(x_{1}+1)-s(x_{2}+1)}\big)\cdot \frac{t(x_{3}+1)}{s(x_{2}+1)-t(x_{3}+1)}\\
=&\frac{-rt(x_1+1)(x_3+1)}{(r(x_{1}+1)-t(x_{3}+1))(r(x_{1}+1)-s(x_{2}+1))},
\end{align*}
and
\begin{align*}
{}^{s_{1}}P_1(srt){}^{s_{1}}P_2(srt)&=\frac{r(x_1+1)}{s(x_{2}+1)-r(x_{1}+1)}\cdot \frac{t(x_{3}+1)}{r(x_{1}+1)-t(x_{3}+1)}\\
&=\frac{-rt(x_1+1)(x_3+1)}{(r(x_{1}+1)-t(x_{3}+1))(r(x_{1}+1)-s(x_{2}+1))}.
\end{align*}
The $\tau_2$-coefficients can be handed similarly. Considering the constant coefficients, we need to show that
\begin{align*}
P_1(rst)&P_2(rst)^{2}+(\tau_2^{2}){}^{s_{2}}Q_2(rts)Q_2(rst){}^{s_{2}}P_1(rts)\\
&=P_2(rst)P_1(rst)^{2}+(\tau_1^{2}){}^{s_{1}}Q_1(srt)Q_1(rst){}^{s_{1}}P_2(srt).
\end{align*}
Using the following identities:
$$
{}^{s_{2}}P_1(rts)={}^{s_{1}}P_2(srt),
$$$$
(\tau_2^{2}){}^{s_{2}}Q_2(rts)Q_2(rst)=(1-P_{2}(rst))(q+P_{2}(rst)),
$$
$$
(\tau_1^{2}){}^{s_{1}}Q_1(srt)Q_1(rst)=(1-P_{1}(rst))(q+P_{1}(rst)),
$$
we need to check that
\begin{align*}
P_2(rst)^{2}&(P_1(rst)-{}^{s_{2}}P_1(rts))+(1-q)P_2(rst){}^{s_{2}}P_1(rts)\\&=P_1(rst)^{2}(P_2(rst)-{}^{s_{1}}P_2(srt))+(1-q)P_1(rst){}^{s_{1}}P_2(srt).
\end{align*}
By an explicit expansion, it is easy to see that the left hand side and right hand side are both equal to
\begin{align*}
(1-q)^{3}\frac{st^{2}(x_2+1)(x_{3}+1)^{2}}{(t(x_{3}+1)-s(x_{2}+1))(t(x_{3}+1)-r(x_{1}+1))(s(x_{2}+1)-r(x_{1}+1))}.
\end{align*}

\subsubsection*{Case 2: $r=s\neq t$.}
\subsubsection*{Case 3: $r\neq s=t$.}
\subsubsection*{Case 4: $r= t\neq s$.}

\

\vspace{0.3cm}\noindent As in the proof of \emph{Case 1}, these three cases can be proved in exactly the same way as in the proof of [BK1, Theorem 4.3, p. 478-479]. We omit the details.

\subsubsection*{Case 5: $r=s=t$.}

\

\vspace{0.3cm}\noindent This case is left as an exercise in the proof of [BK1, Theorem 4.3, p. 479]. Here we shall give a brief proof. In this case, we have $P_{1}(\nu)=P_{2}(\nu)=1$, $Q_{1}(\nu)=qx_2+q-x_1-1$ and $Q_{2}(\nu)=qx_3+q-x_2-1.$ Moreover, By \eqref{commu-relations}, \eqref{ELPQ} equals
\begin{align*}
\begin{split}
&-1+\tau_2Q_2(\nu)+\tau_1Q_1(\nu)-\tau_2Q_2(\nu)\tau_1Q_1(\nu)+\tau_2Q_2(\nu)-\tau_2Q_2(\nu)\tau_2Q_2(\nu)\\&-\tau_1Q_1(\nu)\tau_2Q_2(\nu)
+\tau_2Q_2(\nu)\tau_1Q_1(\nu)\tau_2Q_2(\nu)\\=&-1+\tau_2Q_2(\nu)+\tau_1Q_1(\nu)-\tau_2\tau_1{}^{s_{1}}Q_2(\nu)Q_1(\nu)
-\tau_2\partial_{1}(Q_2(\nu))Q_1(\nu)+\tau_2Q_2(\nu)\\&-\tau_2\partial_{2}(Q_2(\nu))Q_2(\nu)-\tau_1\tau_2{}^{s_{2}}Q_1(\nu)Q_2(\nu)
-\tau_1\partial_{2}(Q_1(\nu))Q_2(\nu)\\&+\tau_2\tau_1\tau_2{}^{s_{2}s_{1}}Q_{2}(\nu){}^{s_{2}}Q_1(\nu)Q_2(\nu)+
\tau_2\tau_1\partial_{2}({}^{s_{1}}Q_2(\nu)){}^{s_{2}}Q_1(\nu)Q_2(\nu)\\
&+\tau_2\partial_{2}(\partial_{1}(Q_2(\nu))){}^{s_{2}}Q_1(\nu)Q_2(\nu)+\tau_2\tau_1{}^{s_{1}}Q_2(\nu)\partial_{2}(Q_1(\nu))Q_2(\nu)\\
&+\tau_2\partial_{1}(Q_2(\nu))\partial_{2}(Q_1(\nu))Q_2(\nu),
\end{split}
\end{align*}
and \eqref{ERPQ} equals
\begin{align*}
\begin{split}
&-1+\tau_1Q_1(\nu)+\tau_2Q_2(\nu)-\tau_1Q_1(\nu)\tau_2Q_2(\nu)+\tau_1Q_1(\nu)-\tau_1Q_1(\nu)\tau_1Q_1(\nu)\\&-\tau_2Q_2(\nu)\tau_1Q_1(\nu)
+\tau_1Q_1(\nu)\tau_2Q_2(\nu)\tau_1Q_1(\nu)\\
=&-1+\tau_1Q_1(\nu)+\tau_2Q_2(\nu)-\tau_1\tau_2{}^{s_{2}}Q_1(\nu)Q_2(\nu)
-\tau_1\partial_{2}(Q_1(\nu))Q_2(\nu)+\tau_1Q_1(\nu)\\
&-\tau_1\partial_{1}(Q_1(\nu))Q_1(\nu)-\tau_2\tau_1{}^{s_{1}}Q_2(\nu)Q_1(\nu)
-\tau_2\partial_{1}(Q_2(\nu))Q_1(\nu)\\
&+\tau_1\tau_2\tau_1{}^{s_{1}s_{2}}Q_{1}(\nu){}^{s_{1}}Q_2(\nu)Q_1(\nu)+
\tau_1\tau_2\partial_{1}({}^{s_{2}}Q_1(\nu)){}^{s_{1}}Q_2(\nu)Q_1(\nu)\\
&+\tau_1\partial_{1}(\partial_{2}(Q_1(\nu))){}^{s_{1}}Q_2(\nu)Q_1(\nu)+\tau_1\tau_2{}^{s_{2}}Q_1(\nu)\partial_{1}(Q_2(\nu))Q_1(\nu)\\
&+\tau_1\partial_{2}(Q_1(\nu))\partial_{1}(Q_2(\nu))Q_1(\nu).
\end{split}
\end{align*}

Since $r=s=t$, we have $\tau_2\tau_1\tau_2=\tau_1\tau_2\tau_1,$ and their corresponding coefficients are equal to each other
by \eqref{Q-relations1}. For the $\tau_1$-coefficients, it suffices to prove that
\begin{equation}
1-\partial_{1}(Q_1(\nu))+\partial_{1}(\partial_{2}(Q_1(\nu))){}^{s_{1}}Q_2(\nu)+\partial_{2}(Q_1(\nu))\partial_{1}(Q_2(\nu))=0.\label{rst-tau1}
\end{equation}
By an explicit calculation, we have $\partial_{1}(Q_1(\nu))=q+1,$ $\partial_{1}(\partial_{2}(Q_1(\nu)))=0,$ $\partial_{2}(Q_1(\nu))=-q,$ $\partial_{1}(Q_2(\nu))=-1.$ Thus, \eqref{rst-tau1} holds. The $\tau_2$-coefficients can be handed similarly. All the other coefficients are routine.

If $j_1, j_2, j_3$ are not all equal, by definition, we have the following identity:
\begin{align*}
g_{i}\diamond 1_{(\nu, j)}=\left\{
\begin{array}{ll}
(\tau_{i}Q_{i}(\nu, j)-P_{i}(\nu, j))1_{(\nu, j)}&\text{if $j_{i}=j_{i+1}$},\\[0.3em]
f_{i, j}\tau_{i}1_{(\nu, j)}&\text{otherwise.}
\end{array}
\right.
\end{align*}
For simplicity, we write $(i_1, i_2, i_3)$ instead of $((\nu_{i_1}, \nu_{i_2}, \nu_{i_3}),(j_{i_1}, j_{i_2}, j_{i_3}))$ or $(j_{i_1}, j_{i_2}, j_{i_3}).$ We need to check that $g_{2}g_{1}g_{2}\diamond 1_{(\nu, j)}=g_{1}g_{2}g_{1}\diamond 1_{(\nu, j)}.$ Then there are four cases for consideration.

\subsubsection*{Case 1: $j_1=j_2\neq j_3$.}

\

\vspace{0.35cm}\noindent By \eqref{rel-def-QHA2}, we have
\begin{align*}
\begin{split}
g_{2}g_{1}g_{2}\diamond 1_{(\nu, j)}&=g_{2}g_{1}\diamond f_{2, (123)}\tau_{2}1_{(123)}\\
&=f_{2, (123)}g_{2}\diamond f_{1, (132)}\tau_{1}\tau_{2}1_{(123)}\\
&=f_{2, (123)}f_{1, (132)}(\tau_{2}Q_{2}(312)-P_{2}(312))\tau_{1}\tau_{2}1_{(123)}\\
&=f_{2, (123)}f_{1, (132)}(\tau_{2}\tau_{1}\tau_{2}{}^{s_{2}s_{1}}Q_{2}(312)-\tau_{1}\tau_{2}{}^{s_{2}s_{1}}P_{2}(312))1_{(123)},
\end{split}
\end{align*}
and similarly, we have
\begin{align*}
\begin{split}
g_{1}g_{2}g_{1}\diamond 1_{(\nu, j)}=f_{2, (213)}f_{1, (231)}\tau_{1}\tau_{2}\tau_{1}Q_{1}(123)1_{(123)}-f_{2, (123)}f_{1, (132)}\tau_{1}\tau_{2}P_{1}(123))1_{(123)}.
\end{split}
\end{align*}
By the assumption on $j_1, j_2$ and $j_3$, we have $\tau_{2}\tau_{1}\tau_{2}=\tau_{1}\tau_{2}\tau_{1}.$ Using the fact that $f_{i, j}=f_{i+1, s_{i}s_{i+1}j}$ and \eqref{P-relations2} and \eqref{Q-relations1}, we see that the corresponding $\tau_{2}\tau_{1}\tau_{2}$-coefficients and $\tau_{1}\tau_{2}$-coefficients are equal to each other in the above two expressions.

\subsubsection*{Case 2: $j_1\neq j_2=j_3$.}

\

\vspace{0.3cm}\noindent Similar.

\subsubsection*{Case 3: $j_1=j_3\neq j_2$.}

\

\vspace{0.3cm}\noindent By the hypothesis, we have $\tau_{1}^{2}1_{(123)}=\tau_{2}^{2}1_{(123)}=1_{(123)}$ and $\tau_{2}\tau_{1}\tau_{2}=\tau_{1}\tau_{2}\tau_{1}.$ Then this case can also be checked by a routine calculation as in \emph{Case 1}.

\subsubsection*{Case 4: $j_1, j_2, j_3$ are all different.}

\

\vspace{0.3cm}\noindent This case can be easily checked.

Next we verify that the actions under $\Psi$ of the generators of $H_{n}(\Gamma)$ satisfy the relations \eqref{rel-def-QHA1}-\eqref{rel-def-QHA6}.

We can see that \eqref{rel-def-QHA1} holds by definition.

The relation \eqref{rel-def-QHA2} easily follows from \eqref{xyyx} and \eqref{phie-ephi}.

The relation \eqref{rel-def-QHA3} easily follows from \eqref{xyyx}, \eqref{phi-phi} and \eqref{phi-q}.

Next we check the relation \eqref{rel-def-QHA4}. If $a=i+1$, we need to prove that
\begin{align*}
\tau_{i}x_{i+1}1_{(\nu, j)}\ast n-x_{i}\tau_{i}1_{(\nu, j)}\ast n=\left\{
\begin{array}{ll}
1_{(\nu, j)}\ast n&\text{if $(\nu_{i}, j_{i})=(\nu_{i+1}, j_{i+1})$},\\[0.3em]
0&\text{otherwise,}
\end{array}
\right.
\end{align*}
for all $n\in N$ with an $N\in \mathcal{C}_{K}.$ To simplify notation for the remainder of the proof, we no longer write the elements ``$\ast n$" on the right hand side of all expressions, but remember it is always there.

If $(\nu_{i}, j_{i})=(\nu_{i+1}, j_{i+1}),$ we have
\begin{align*}
\tau_{i}x_{i+1}1_{(\nu, j)}=&(g_{i}+1)Q_{i}'(\nu, j)^{-1}(\nu_{i+1}^{-1}X_{i+1}-1)e(\nu, j)\\
=&((\nu_{i+1}^{-1}X_{i}-1)(g_{i}+1)+\nu_{i}^{-1}(qX_{i+1}-X_{i}))Q_{i}'(\nu, j)^{-1}e(\nu, j)\\
=&(x_{i}\tau_{i}+1)1_{(\nu, j)}.
\end{align*}

If $j_{i}=j_{i+1}$ and $\nu_{i}\neq \nu_{i+1}$, we have
\begin{align*}
\tau_{i}x_{i+1}1_{(\nu, j)}=&\Phi_{i}Q_{i}'(\nu, j)^{-1}(\nu_{i+1}^{-1}X_{i+1}-1)e(\nu, j)\\
=&(\nu_{i+1}^{-1}X_{i}-1)\Phi_{i}Q_{i}'(\nu, j)^{-1}e(\nu, j)\text{ by }\eqref{phi-x-nuj1}\\
=&x_{i}\tau_{i}1_{(\nu, j)}.
\end{align*}

If $j_{i}\neq j_{i+1}$, we have
\begin{align*}
\tau_{i}x_{i+1}1_{(\nu, j)}=&g_{i}\cdot f_{i, j}^{-1}(\nu_{i+1}^{-1}X_{i+1}-1)e(\nu, j)\\
=&(\nu_{i+1}^{-1}X_{i}-1)g_{i}\cdot f_{i, j}^{-1}e(\nu, j)\text{ by }\eqref{gxe-xge}\\
=&x_{i}\tau_{i}1_{(\nu, j)}.
\end{align*}

For $a=i,$ the proof is similar.

If $a\neq i, i+1,$ we have $\tau_{i}x_{a}1_{(\nu, j)}-x_{s_{i}a}\tau_{i}1_{(\nu, j)}=0$ by \eqref{phi-x}.

Since we have verified \eqref{rel-def-QHA4}, we can conclude that the identity \eqref{commu-relations} holds. For the relation \eqref{rel-def-QHA5}, by \eqref{rel-def-QHA2}, we have
\begin{align*}
\tau_{i}^{2}1_{(\nu, j)}=\Phi_{i}Q_{i}'(s_{i}\cdot(\nu, j))^{-1}(\tau_{i}1_{(\nu, j)}).
\end{align*}

If $(\nu_{i}, j_{i})=(\nu_{i+1}, j_{i+1}),$ we have
\begin{align*}
\tau_{i}^{2}1_{(\nu, j)}=&(g_{i}+1)(q\nu_{i+1}^{-1}X_{i+1}-\nu_{i}^{-1}X_{i})^{-1}(\tau_{i}1_{(\nu, j)})\\
=&(g_{i}+1)((q(x_{i+1}+1)-(x_{i}+1))^{-1}\tau_{i}1_{(\nu, j)}).
\end{align*}
Using \eqref{commu-relations}, we get
\begin{align*}
(q(x_{i+1}+1)-(x_{i}+1))^{-1}\tau_{i}1_{(\nu, j)}=&\tau_{i}(q(x_{i}+1)-(x_{i+1}+1))^{-1}1_{(\nu, j)}
-(q+1)\\\times(q(x_{i+1}+&1)-(x_{i}+1))^{-1}(q(x_{i}+1)-(x_{i+1}+1))^{-1}1_{(\nu, j)}.
\end{align*}
Thus, we have
\begin{align*}
\tau_{i}^{2}1_{(\nu, j)}=&(g_{i}+1)(\tau_{i}(q(x_{i}+1)-(x_{i+1}+1))^{-1}1_{(\nu, j)}
-(q+1)\\&\times(q(x_{i+1}+1)-(x_{i}+1))^{-1}(q(x_{i}+1)-(x_{i+1}+1))^{-1}1_{(\nu, j)})\\
=&(g_{i}+1)((g_{i}+1)Q_{i}'(\nu, j)^{-1}(q\nu_{i}^{-1}X_{i}-\nu_{i+1}^{-1}X_{i+1})^{-1}-(q+1)\\
&\times(q\nu_{i+1}^{-1}X_{i+1}-
\nu_{i}^{-1}X_{i})^{-1}(q\nu_{i}^{-1}X_{i}-\nu_{i+1}^{-1}X_{i+1})^{-1})e(\nu, j)\\
=&(g_{i}+1)(g_{i}-q)Q_{i}'(\nu, j)^{-1}(q\nu_{i}^{-1}X_{i}-\nu_{i+1}^{-1}X_{i+1})^{-1}e(\nu, j)\\
=&0.
\end{align*}

If $j_{i}=j_{i+1}$ and $\nu_{i}\neq \nu_{i+1}$, by \eqref{commu-relations}, we have
\begin{align*}
\tau_{i}^{2}1_{(\nu, j)}=&\Phi_{i}(Q_{i}(s_{i}\cdot(\nu, j))^{-1}\tau_{i}1_{(\nu, j)})\\
=&\Phi_{i}(\tau_{i}{}^{s_{i}}Q_{i}(s_{i}\cdot(\nu, j))^{-1}1_{(\nu, j)})\\
=&\Phi_{i}^{2}Q_{i}'(\nu, j)^{-1}{}^{s_{i}}Q_{i}'(s_{i}\cdot(\nu, j))^{-1}e(\nu, j).
\end{align*}
Since
\begin{align}
(1-P_{i}'(\nu, j))(q+P_{i}'(\nu, j))e(\nu, j)=&(1-\frac{1-q}{1-X_{i}X_{i+1}^{-1}})(q+\frac{1-q}{1-X_{i}X_{i+1}^{-1}})e(\nu, j)\notag\\
=&\frac{(qX_{i+1}-X_{i})(X_{i+1}-qX_i)}{(X_{i+1}-X_{i})^{2}}e(\nu, j)\label{p-ralation}\\
=&\Phi_{i}^{2}e(\nu, j)\text{ by }\eqref{phi-2-nuj1}\notag,
\end{align}
we see that \eqref{rel-def-QHA5} holds by \eqref{Q-relations2}.

If $j_{i}\neq j_{i+1}$, we have
\begin{align*}
\tau_{i}^{2}1_{(\nu, j)}=&g_{i}\cdot f_{i, s_{i}(j)}^{-1}(\tau_{i}1_{(\nu, j)})\\
=&f_{i, s_{i}(j)}^{-1}g_{i}\cdot g_{i}\cdot f_{i, j}^{-1}e(\nu, j)\\
=&(f_{i, j}f_{i, s_{i}(j)})^{-1}g_{i}^{2}e(\nu, j)\\
=&q^{-1}\cdot qe(\nu, j)=1_{(\nu, j)}.
\end{align*}

Finally we prove \eqref{rel-def-QHA6}. Without loss of generality we assume that $i=1$ and $n=3,$ and we need to show that \eqref{rel-def-QHA6} holds for any $\alpha=(\nu, j)\in K^{3}$ with $\nu=(\nu_1, \nu_2, \nu_3)$ and $j=(j_1, j_2, j_3).$

If $j_1=j_2=j_3$, we set $i:=\nu_1, l:=\nu_2, k:=\nu_3.$ We stop writing $j=(j_1, j_2, j_3)$ in the expressions of $1_{(\nu, j)}$, $e(\nu, j)$, $Q_{a}(\nu, j)$ and $P_{a}(\nu, j)$, that is, we write $1_{\nu}$ instead of $1_{(\nu, j)}$, $e(\nu)$ instead of $e(\nu, j),$ $Q_{a}(\nu)$ instead of $Q_{a}(\nu, j)$ and $P_{a}(\nu)$ instead of $P_{a}(\nu, j)$ for $a=1,2.$ To show that \eqref{rel-def-QHA6} holds, it suffices to consider the following five cases.

\subsubsection*{Case 1: $i, l, k$ are all different.}
\subsubsection*{Case 2: $i=l\neq k$.}
\subsubsection*{Case 3: $i\neq l=k$.}


\

\vspace{0.3cm}\noindent In these three cases, we need to show that $\tau_{1}\tau_{2}\tau_{1}1_{\nu}=\tau_{2}\tau_{1}\tau_{2}1_{\nu},$ which can be proved in exactly the same way as in the proof of [BK1, Theorem 4.2, p. 475] by using \eqref{phi-braid}. We omit the details.

\subsubsection*{Case 4: $i=k\neq l$.}

\

\vspace{0.3cm}\noindent In this case, we have
\begin{align*}
&\tau_{1}\tau_{2}\tau_{1}1_{\nu}\\
=&\Phi_{1}\Phi_{2}\Phi_{1}((Q_{1}(ili){}^{s_{1}}Q_{2}(lii){}^{s_{1}s_{2}}Q_{1}(lii))^{-1}1_{\nu})
+\Phi_{1}^{2}(Q_{1}(ili)^{-1}({}^{s_{1}}\partial_{2}(Q_1(lii)^{-1}))1_{\nu}),
\end{align*}
and
\begin{align*}
&\tau_{2}\tau_{1}\tau_{2}1_{\nu}\\
=&\Phi_{2}\Phi_{1}\Phi_{2}((Q_{2}(ili){}^{s_{2}}Q_{1}(iil){}^{s_{2}s_{1}}Q_{2}(iil))^{-1}1_{\nu})
+\Phi_{2}^{2}(Q_{2}(ili)^{-1}({}^{s_{2}}\partial_{1}(Q_2(iil)^{-1}))1_{\nu}).
\end{align*}
Using \eqref{Q-relations1}, \eqref{phi-2-nuj1} and \eqref{phi-braid}, we get that $\tau_{1}\tau_{2}\tau_{1}1_{\nu}-\tau_{2}\tau_{1}\tau_{2}1_{\nu}=A+B-C$, where
\begin{align*}
A=&(1-q)^2\frac{(X_1X_{3}-X_{2}^2)(X_1 X_{2}-qX_{2}X_{3})}{(X_1-X_{2})^2(X_{2}-X_{3})^2}((Q_{1}(ili){}^{s_{1}}Q_{2}(lii)Q_{2}(ili))^{-1}1_{\nu}),\\
B=&\frac{(X_{2}-qX_1)(X_1-qX_{2})}{(X_{2}-X_{1})(X_{1}-X_{2})}(Q_{1}(ili)^{-1}({}^{s_{1}}\partial_{2}(Q_1(lii)^{-1}))1_{\nu}),\\
C=&\frac{(X_{3}-qX_2)(X_2-qX_{3})}{(X_{3}-X_{2})(X_{2}-X_{3})}(Q_{2}(ili)^{-1}({}^{s_{2}}\partial_{1}(Q_2(iil)^{-1}))1_{\nu}).
\end{align*}
Noting that $Q_{2}(lii)1_{\nu}=i^{-1}(qX_{3}-X_{2})e(\nu),$ we get that
\begin{align*}
A=-i(1-q)^2\frac{(X_1X_{3}-X_{2}^2)X_{2}}{(X_1-X_{2})^2(X_{2}-X_{3})^2}((Q_{1}(ili)Q_{2}(ili))^{-1}1_{\nu}).
\end{align*}
Since
\begin{align*}\partial_{2}(Q_1(lii)^{-1})1_{\nu}=\frac{Q_1(lii)^{-1}-{}^{s_{2}}Q_1(lii)^{-1}}{x_{3}-x_{2}}1_{\nu}=
\frac{Q_1(lii)^{-1}-{}^{s_{1}}Q_2(ili)^{-1}}{x_{3}-x_{2}}1_{\nu},
\end{align*}
we have
\begin{align*}
B=\frac{(X_{2}-qX_1)(X_1-qX_{2})}{(X_{2}-X_{1})(X_{1}-X_{2})}\big(\frac{Q_{1}(ili)^{-1}Q_{2}(ili)^{-1}-
Q_{1}(ili)^{-1}({}^{s_{1}}Q_{1}(lii)^{-1})}{x_{1}-x_{3}}1_{\nu}\big).
\end{align*}
Similarly, we have
\begin{align*}
C=\frac{(X_{3}-qX_2)(X_2-qX_{3})}{(X_{3}-X_{2})(X_{2}-X_{3})}\big(\frac{Q_{1}(ili)^{-1}Q_{2}(ili)^{-1}-
Q_{2}(ili)^{-1}({}^{s_{2}}Q_{2}(iil)^{-1})}{x_{1}-x_{3}}1_{\nu}\big).
\end{align*}
Note that $(x_{1}-x_{3})1_{\nu}=i^{-1}(X_{1}-X_{3})e(\nu).$ By a direct computation we have the identity:
\begin{align*}
-i(1-q)^2& \frac{(X_1X_3-X_2^2)X_2}{(X_1-X_2)^2
(X_2-X_3)^2}
-\frac{i(X_2-qX_1)(X_1-qX_2)}{(X_1-X_2)^2(X_1-X_3)}\\
+&\frac{i(X_3-qX_2)(X_2-qX_3)}{(X_2-X_3)^2(X_1-X_3)}=0.
\end{align*}
Thus, we get that
\begin{align*}
A+B-C=&-\frac{(X_{2}-qX_1)(X_1-qX_{2})}{(X_{2}-X_{1})(X_{1}-X_{2})}\big(\frac{(Q_{1}(ili){}^{s_{1}}Q_{1}(s_{1}\cdot(ili)))^{-1}}{x_{1}-x_{3}}1_{\nu}\big)\\
&+\frac{(X_{3}-qX_2)(X_2-qX_{3})}{(X_{3}-X_{2})(X_{2}-X_{3})}\big(\frac{(Q_{2}(ili){}^{s_{2}}Q_{2}(s_{2}\cdot(ili)))^{-1}}{x_{1}-x_{3}}1_{\nu}\big).
\end{align*}
By using \eqref{Q-relations2} and \eqref{p-ralation}, we deduce that this equals 0 if $i\nslash l$, $1_{\nu}$ if $i\rightarrow l$, $-1_{\nu}$ if $i\leftarrow l$, and $(-2x_2+x_1+x_3)1_{\nu}$ if $i\rightleftarrows l.$ Thus, \eqref{rel-def-QHA6} holds.


\subsubsection*{Case 5: $i=l=k$.}

\

\vspace{0.3cm}\noindent This case is left as an exercise in the proof of [BK1, Theorem 4.2, p. 476]. Here we shall give a brief proof. In this case, by \eqref{Q-relations1}, we have
\begin{align*}
\tau_{1}\tau_{2}\tau_{1}1_{\nu}=&\Phi_{1}\Phi_{2}\Phi_{1}((Q_{1}(iii){}^{s_{2}}Q_{1}(iii)Q_{2}(iii))^{-1}1_{\nu})\\
&+\Phi_{1}^{2}(Q_{1}(iii)^{-1}({}^{s_{1}}\partial_{2}(Q_1(iii)^{-1}))1_{\nu})+\Phi_{1}(\partial_{1}(\partial_{2}(Q_1(iii)^{-1}))1_{\nu}),
\end{align*}
and
\begin{align*}
\tau_{2}\tau_{1}\tau_{2}1_{\nu}=&\Phi_{2}\Phi_{1}\Phi_{2}((Q_{2}(iii){}^{s_{1}}Q_{2}(iii)Q_{1}(iii))^{-1}1_{\nu})\\
&+\Phi_{2}^{2}(Q_{2}(iii)^{-1}({}^{s_{2}}\partial_{1}(Q_2(iii)^{-1}))1_{\nu})+\Phi_{2}(\partial_{2}(\partial_{1}(Q_2(iii)^{-1}))1_{\nu}).
\end{align*}
Using \eqref{Q-relations1}, \eqref{phi-braid} and the fact that $\Phi_{1}^{2}e(\nu)=(1+q)\Phi_{1}e(\nu)$ and $\Phi_{2}^{2}e(\nu)=(1+q)\Phi_{2}e(\nu),$ we see that $\tau_{1}\tau_{2}\tau_{1}1_{\nu}-\tau_{2}\tau_{1}\tau_{2}1_{\nu}=\Phi_{1}(D1_{\nu})-\Phi_{2}(E1_{\nu}),$
where
\begin{align*}
D=q(Q_{1}(iii){}^{s_{2}}Q_{1}(iii)Q_{2}(iii))^{-1}+(1+q)Q_{1}(iii)^{-1}({}^{s_{1}}\partial_{2}(Q_1(iii)^{-1}))
+\partial_{1}(\partial_{2}(Q_1(iii)^{-1})),
\end{align*}
and
\begin{align*}
E=q(Q_{1}(iii){}^{s_{2}}Q_{1}(iii)Q_{2}(iii))^{-1}+(1+q)Q_{2}(iii)^{-1}({}^{s_{2}}\partial_{1}(Q_2(iii)^{-1}))
+\partial_{2}(\partial_{1}(Q_2(iii)^{-1})).
\end{align*}
In order to show that $\tau_{1}\tau_{2}\tau_{1}1_{\nu}=\tau_{2}\tau_{1}\tau_{2}1_{\nu},$ it suffices to prove that $D=E=0.$ By a direct computation, we have
\begin{align*}
q(Q_{1}(iii){}^{s_{2}}Q_{1}(iii)Q_{2}(iii))^{-1}=\frac{q}{(qx_2-x_1)(qx_3-x_2)(qx_3-x_1)},
\end{align*}
\begin{align*}
(1+q)Q_{1}(iii)^{-1}({}^{s_{1}}\partial_{2}(Q_1(iii)^{-1}))=\frac{q(1+q)}{(qx_2-x_1)(qx_3-x_2)(qx_1-x_2)},
\end{align*}
\begin{align*}
\partial_{1}(\partial_{2}(Q_1(iii)^{-1}))=\frac{q(x_1+x_2-qx_3-q^{2}x_3)}{(qx_2-x_1)(qx_3-x_1)(qx_1-x_2)(qx_3-x_2)}.
\end{align*}
Then it is easy to see that $D=0.$ Similarly, we have $E=0.$ Thus, \eqref{rel-def-QHA6} holds.

If $j_1, j_2, j_3$ are not all equal, by definition, we have the following identity:\vspace{0.1cm}
\begin{align*}
