(g_{i}+1)Q_{i}'(\nu, j)^{-1}e(\nu, j)&\text{if $\nu_{i}=\nu_{i+1}$ and $j_{i}=j_{i+1}$},\\[0.3em]
f_{i, j}^{-1}g_{i}e(\nu, j)&\text{if $j_{i}\neq j_{i+1}$.}
